var OrganizationAdministrationRepository = class {
  static {
    __name(this, "OrganizationAdministrationRepository");
  }
  // find
  async findUserByEmail(input2) {
    return prismaBinding.user.findUnique({
      where: {
        tenant_id_email: {
          email: input2.email,
          tenant_id: input2.tenant_id
        }
      }
    });
  }
  async findMembersByCompanyId(input2) {
    return prismaBinding.companyMembership.findMany({
      where: {
        company_id: input2.company_id,
        tenant_id: input2.tenant_id
      },
      include: {
        user: true,
        role: true
      }
    });
  }
  async findCompanyMemberByEmail(input2) {
    return prismaBinding.companyMembership.findFirst({
      where: {
        company_id: input2.company_id,
        tenant_id: input2.tenant_id,
        user: {
          email: input2.email
        }
      },
      include: {
        user: true,
        role: true
      }
    });
  }
  async findCompanyMemberByUserId(input2) {
    return prismaBinding.companyMembership.findFirst({
      where: {
        company_id: input2.company_id,
        tenant_id: input2.tenant_id,
        user_id: input2.user_id
      },
      include: {
        user: true,
        role: true
      }
    });
  }
  async findRoleById(input2) {
    return prismaBinding.role.findFirst({
      where: {
        id: input2.role_id,
        company_id: input2.company_id,
        tenant_id: input2.tenant_id
      }
    });
  }
  async findRolesByCompanyId(input2) {
    return prismaBinding.role.findMany({
      where: {
        tenant_id: input2.tenant_id,
        company_id: input2.company_id
      }
    });
  }
  async findRolePermissions(input2) {
    return prismaBinding.rolePermission.findMany({
      where: {
        role_id: input2.role_id,
        role: {
          tenant_id: input2.tenant_id,
          company_id: input2.company_id
        }
      },
      include: {
        permission: true
      }
    });
  }
  async findPermissions() {
    return prismaBinding.permission.findMany();
  }
  async findCompanySettings(input2) {
    return prismaBinding.company.findUnique({
      where: {
        id: input2.company_id
      }
    });
  }
  // create
  async createInvitation(input2) {
    return prismaBinding.companyInvitation.create({
      data: {
        tenant_id: input2.tenant_id,
        company_id: input2.company_id,
        email: input2.email,
        invited_by: input2.invited_by,
        invite_token_hash: input2.invite_token_hash
      }
    });
  }
  async createRole(input2) {
    const code = input2.name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
    return prismaBinding.role.create({
      data: {
        name: input2.name,
        description: input2.description,
        company_id: input2.company_id,
        tenant_id: input2.tenant_id,
        code
      }
    });
  }
  // update
  async updateMember(input2) {
    return prismaBinding.companyMembership.update({
      where: {
        tenant_id_company_id_user_id: {
          tenant_id: input2.tenant_id,
          company_id: input2.company_id,
          user_id: input2.user_id
        }
      },
      data: {
        role_id: input2.update.role_id,
        employment_status: input2.update.employment_status,
        job_title: input2.update.jobTitle
      }
    });
  }
  async assignRole(input2) {
    return prismaBinding.userRole.create({
      data: {
        user_id: input2.user_id,
        company_id: input2.company_id,
        tenant_id: input2.tenant_id,
        role_id: input2.role_id
      }
    });
  }
  async assignPermissionsToRole(input2) {
    return prismaBinding.rolePermission.createMany({
      data: input2,
      skipDuplicates: true
    });
  }
  async updateRole(input2) {
    return prismaBinding.role.update({
      where: {
        id: input2.role_id
      },
      data: {
        name: input2.update.name,
        description: input2.update.description
      }
    });
  }
  async updateCompanySettings(input2) {
    return prismaBinding.company.update({
      where: {
        id: input2.company_id
      },
      data: {
        contact_email: input2.update.companyEmail,
        display_name: input2.update.displayName,
        legal_name: input2.update.legalName,
        contact_phone: input2.update.contactNumber,
        address: input2.update.address
      }
    });
  }
  // remove / delete
  async removeMember(input2) {
    return prismaBinding.companyMembership.deleteMany({
      where: {
        company_id: input2.company_id,
        tenant_id: input2.tenant_id,
        user_id: input2.user_id
      }
    });
  }
  async deleteRole(role_id) {
    return prismaBinding.role.delete({
      where: {
        id: role_id
      }
    });
  }
  async deletePermissionFromRole(input2) {
    return prismaBinding.rolePermission.deleteMany({
      where: {
        role_id: input2.role_id,
        permission_id: input2.permission_id
      }
    });
  }
  async removeRoleFromMember(input2) {
    return prismaBinding.userRole.deleteMany({
      where: {
        company_id: input2.company_id,
        tenant_id: input2.tenant_id,
        user_id: input2.user_id,
        role_id: input2.role_id
      }
    });
  }
};

// src/modules/organization_administration/organizationAdministrationRouter.ts
function createOrganizationAdministration() {
  const router = new Hono2();
  const service2 = new OrganizationAdministrationService(new OrganizationAdministrationRepository());
  const controller = new OrganizationAdministrationController(service2);
  router.use(authenticate);
  router.post("/members", Authorize(systemPermissions.organizationManagement.inviteMember), controller.addMember);
  router.get("/members", Authorize(systemPermissions.organizationManagement.readMember), controller.getMember);
  router.get("/members/:userId", Authorize(systemPermissions.organizationManagement.readMember), controller.getUser);
  router.patch("/members/:userId", Authorize(systemPermissions.organizationManagement.updateMember), controller.updateMember);
  router.delete("/members/:userId", Authorize(systemPermissions.organizationManagement.removeMember), controller.removeMember);
  router.post("/roles", Authorize(systemPermissions.organizationManagement.createRole), controller.role);
  router.post("/members/:userId/roles", Authorize(systemPermissions.organizationManagement.updateMember), controller.assignRoleToMember);
  router.post("/roles/:roleId/permissions", Authorize(systemPermissions.organizationManagement.addRolePermission), controller.assignPermissionsToRole);
  router.get("/roles", Authorize(systemPermissions.organizationManagement.readRole), controller.getRoles);
  router.get("/roles/:roleId", Authorize(systemPermissions.organizationManagement.readRole), controller.getRole);
  router.get("/roles/:roleId/permissions", Authorize(systemPermissions.organizationManagement.readRole), controller.getRolePermissions);
  router.get("/permissions", Authorize(systemPermissions.organizationManagement.readRole), controller.getPermissions);
  router.patch("/roles/:roleId", Authorize(systemPermissions.organizationManagement.updateRole), controller.updateRole);
  router.delete("/roles/:roleId", Authorize(systemPermissions.organizationManagement.deleteRole), controller.deleteRole);
  router.delete("/roles/:roleId/permissions/:permissionId", Authorize(systemPermissions.organizationManagement.removeRolePermission), controller.deletePermissionsFromRole);
  router.delete("/members/:userId/roles/:roleId", Authorize(systemPermissions.organizationManagement.updateMember), controller.removeRoleFromMember);
  router.get("/settings", Authorize(systemPermissions.organizationManagement.read), controller.settings);
  router.patch("/settings", Authorize(systemPermissions.organizationManagement.update), controller.updateSettings);
  return router;
}
__name(createOrganizationAdministration, "createOrganizationAdministration");

