var UserManagementRepository = class {
  static {
    __name(this, "UserManagementRepository");
  }
  async registerCompany(data) {
    return prismaBinding.$transaction(async (tx) => {
      const existingMembership = await tx.companyMembership.findFirst({
        where: {
          user_id: data.userId,
          tenant_id: data.tenantId
        },
        select: {
          id: true
        }
      });
      if (existingMembership) {
        return { status: "duplicate" };
      }
      const ownerRole = await tx.role.findFirst({
        where: {
          code: "ORGANIZATION_ADMIN",
          is_system: true,
          tenant_id: null
        }
      });
      if (!ownerRole) {
        return { status: "missing_role" };
      }
      const company = await tx.company.create({
        data: {
          tenant_id: data.tenantId,
          legal_name: data.legal_name,
          display_name: data.display_name,
          tax_id: data.tax_id,
          address: data.address,
          contact_email: data.contact_email,
          contact_phone: data.contact_phone
        }
      });
      await tx.companyMembership.create({
        data: {
          user_id: data.userId,
          company_id: company.id,
          tenant_id: data.tenantId,
          role_id: ownerRole.id,
          employment_status: "ACTIVE"
        }
      });
      await tx.userRole.create({
        data: {
          user_id: data.userId,
          company_id: company.id,
          tenant_id: data.tenantId,
          role_id: ownerRole.id
        }
      });
      return {
        status: "created",
        company
      };
    }, {
      isolationLevel: "Serializable"
    });
  }
  async findById(userId, tenantId) {
    return prismaBinding.user.findUnique({
      where: {
        id: userId,
        tenant_id: tenantId
      }
    });
  }
  async updateProfile(data) {
    const result = await prismaBinding.user.updateMany({
      where: {
        id: data.userId,
        tenant_id: data.tenantId
      },
      data: {
        first_name: data.first_name,
        last_name: data.last_name,
        email: data.email,
        job_title: data.job_title
      }
    });
    if (result.count === 0) {
      return null;
    }
    return this.findById(data.userId, data.tenantId);
  }
  async createCompany(data) {
    return prismaBinding.company.create({
      data: {
        tenant_id: data.tenantId,
        legal_name: data.legal_name,
        display_name: data.display_name,
        tax_id: data.tax_id,
        address: data.address,
        contact_email: data.contact_email,
        contact_phone: data.contact_phone
      }
    });
  }
  async createCompanyMembership(data) {
    return prismaBinding.companyMembership.create({
      data: {
        user_id: data.userId,
        company_id: data.companyId,
        tenant_id: data.tenantId,
        employment_status: "ACTIVE"
      }
    });
  }
  async createUserRole(data) {
    return prismaBinding.userRole.create({
      data: {
        user_id: data.userId,
        company_id: data.companyId,
        tenant_id: data.tenantId,
        role_id: data.roleId
      }
    });
  }
  async findRoleByCode(code) {
    return prismaBinding.role.findFirst({
      where: {
        code,
        is_system: true
      }
    });
  }
  async findSystemRoleByCode(code) {
    return prismaBinding.role.findFirst({
      where: {
        code,
        is_system: true,
        tenant_id: null
      }
    });
  }
};

// src/modules/user_management/userManagementService.ts
var UserManagementService = class {
  constructor(repository, eventBus2) {
    this.repository = repository;
    this.eventBus = eventBus2;
  }
  repository;
  eventBus;
  static {
    __name(this, "UserManagementService");
  }
  // get
  async profile(userId, tenantId) {
    const user = await this.repository.findById(userId, tenantId);
    if (!user) {
      throw new NotFoundError("User Not Found");
    }
    return this.toProfileResponse(user);
  }
  // patch
  async updateProfile(userId, tenantId, input2) {
    const isExist = await this.repository.findById(userId, tenantId);
    if (!isExist) {
      throw new NotFoundError("User Not Found");
    }
    const updateData = {
      userId,
      tenantId,
      ...input2
    };
    const updatedUser = await this.repository.updateProfile(updateData);
    if (!updatedUser) {
      throw new NotFoundError("User Not Found");
    }
    return this.toProfileResponse(updatedUser);
  }
  // post
  async companyRegister(userId, tenantId, input2) {
    const user = await this.repository.findById(userId, tenantId);
    if (!user) {
      throw new NotFoundError("User Not Found");
    }
    const userData = {
      userId: user.id,
      tenantId
    };
    const registration = await this.repository.registerCompany({
      userId: userData.userId,
      tenantId: userData.tenantId,
      ...input2
    });
    if (registration.status === "duplicate") {
      throw new ConflictError(
        "User is already associated with an organization"
      );
    }
    if (registration.status === "missing_role") {
      throw new NotFoundError("Organization Admin role not found");
    }
    await this.eventBus.publish(
      "organization.registered",
      {
        companyId: registration.company.id,
        tenantId,
        userId
      }
    );
    return {
      companyId: registration.company.id,
      companyName: registration.company.display_name
    };
  }
  toProfileResponse(user) {
    return {
      user_id: user.id,
      first_name: user.first_name,
      last_name: user.last_name,
      email: user.email,
      job_title: user.job_title ?? null,
      status: user.status
    };
  }
};

